package com.flinkweb.service.ai.support;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.List;
/** 版本感知的SQL开发技能，借鉴Flink Agents工具/上下文编排，复用平台Parser和候选审阅。 */
public final class AiSqlGenerationSkill {
  /** 返回按需技能资料，不将示例描述为真实业务schema或Planner证明。 */
  public static ObjectNode guide(ObjectMapper mapper,String version,String topic){var out=mapper.createObjectNode().put("flinkVersion",version.isBlank()?"UNKNOWN":version).put("topic",topic).put("verification","静态Parser通过不证明Catalog、Connector、Planner、Sink语义和生产执行成功");out.put("documentedVersion","1.20").put("versionNotice",version.startsWith("1.20")?"使用登记镜像及对应Parser再次核对":"当前资料针对1.20；其他版本需先核对官方语法和依赖，不能声称支持已验证");out.putArray("workflow").add("读取runtime_image_list和context_read(draft/runtimeImages)，确定真实Flink版本").add("通过catalog_metadata/catalog_functions发现表、列、主键、函数，按需读取避免全量上下文").add("明确Source/Sink、时间语义、Watermark、状态增长和变更流能力；只询问业务必要缺口").add("生成完整DDL/DML，复用平台配置引用，不虚构凭据、表结构或依赖").add("sql_check/sql_validate_candidate静态检查，依据错误行号修正后用sql_propose登记完整候选").add("用户审阅后保存；真实SQL验证和发布运行另外确认Source/Sink影响");var rules=out.putArray("rules");for(String rule:List.of("持续任务省略datagen number-of-rows，不使用-1；TIMESTAMP(3)和Watermark定义在DDL中","窗口聚合明确事件时间/处理时间、窗口大小、迟到和时区；无界JOIN明确时间边界和状态保留","去重明确ROW_NUMBER分区键、排序和更新流，下游须支持对应changelog；主键NOT ENFORCED不是实际去重","Flink 1.20使用已验证语法，不生成CREATE AGENT/CREATE TOOL/AI_RUN_AGENT等厂商或其他版本扩展","示例可用datagen/print，但真实业务不得替换Source/Sink；未知字段保留待确认项","多INSERT考虑StatementSet，checkpoint和交付语义取决于Connector和运行配置"))rules.add(rule);try{out.put("example",new org.springframework.core.io.ClassPathResource("ai/sql-generation-example.sql").getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}catch(java.io.IOException ex){throw new IllegalStateException("SQL示例资源缺失",ex);}out.putArray("references").add("https://nightlies.apache.org/flink/flink-agents-docs-main/docs/development/tool_use/").add("https://nightlies.apache.org/flink/flink-docs-release-1.20/docs/connectors/table/datagen/").add("https://nightlies.apache.org/flink/flink-docs-release-1.20/docs/dev/table/sql/queries/window-tvf/");return out;}
}
